import subprocess, json, shutil, re
from diff import diff_syntax_spec
print("syntaxes:", len(diff_syntax_spec), "; option nodes in syntax 0:", len(diff_syntax_spec[0][0]), "; operands:", [(n.kind, n.arity.name) for n in diff_syntax_spec[0][1]])
F1="/tmp/difftest/f1"; F2="/tmp/difftest/f2"
def run(args):
    p=subprocess.run(["/usr/bin/diff",*args],capture_output=True,text=True); return p.returncode, p.stderr
sample={"Integer":"2","Regex":"x","String":"lab","Glob":"*.o","Path":"/dev/null","Format":"%L","Selection":"always","List":"ad=1"}
bad=[]
# 1) syntax spec vs binary
for node in diff_syntax_spec[0][0]:
    for sp in [node.flag]+node.alias:
        if node.kind=="Flag":
            rc,err=run([sp,F1,F2])
            if rc==2: bad.append(("flag rejected",sp,err.strip()))
            # a flag must not swallow the next word: with 3 words after it we expect "extra operand"
            rc,err=run([sp,F1,F2,F1])
            if "extra operand" not in err: bad.append(("flag seems to take an argument",sp,err.strip()))
        else:
            val=sample[node.kind]
            if node.eq:
                rc,err=run([f"{sp}={val}",F1,F2])
                if rc==2: bad.append(("eq-option rejected",sp,err.strip()))
                if node.kind in("Integer","Selection"):  # optional value: bare form must work
                    rc,err=run([sp,F1,F2])
                    if rc==2: bad.append(("bare optional-arg option rejected",sp,err.strip()))
            else:
                rc,err=run([sp,val,F1,F2])
                if rc==2: bad.append(("option rejected",sp,err.strip()))
                if sp.startswith("--"):
                    rc,err=run([f"{sp}={val}",F1,F2])
                    if rc==2: bad.append(("option= rejected",sp,err.strip()))
                rc,err=run([sp,val,F1])  # must consume val: then only 1 operand -> missing operand
                if "missing operand" not in err: bad.append(("option did not consume argument",sp,err.strip()))
print("syntax-spec problems:", bad or "none")
